insert into public.question_versions(id,question_id,version,title,skill,content_blocks,content_review,prompt_version) values('10000000-0000-4000-8000-000000000001','cpp-lifetime-v1',1,'A view outlives its owner','C++ · Object lifetime','[{"type":"text","text":"A service returns a cheap view of a generated label. Is the caller''s use valid in C++20? Explain the lifetime issue and propose an ownership-safe interface."},{"type":"code","language":"cpp","text":"std::string_view label() {\n  std::string value = \"worker-42\";\n  return value;\n}\nauto name = label();\nstd::cout << name;"}]'::jsonb,'candidate','candidate-content-v1');
insert into private.rubrics(question_version_id,version,pass_score,required_claims,reference_answer) values('10000000-0000-4000-8000-000000000001','rubric-v1',3,array['The local string is destroyed at function return.','string_view does not own or extend the string lifetime.','Reading the dangling view has undefined behavior; return an owning string.'],'value dies at return. string_view stores a pointer and length without ownership, so the caller reads dangling storage and has undefined behavior. Return std::string by value; move/elision avoids needing an unsafe view. Static storage or caller-owned storage could work only with explicit lifetime guarantees.');
insert into public.question_versions(id,question_id,version,title,skill,content_blocks,content_review,prompt_version) values('10000000-0000-4000-8000-000000000002','cpp-publication-v1',1,'Publishing data across threads','C++ · Memory ordering','[{"type":"text","text":"Assume data is initially 0 and ready is initially false. Each thread runs once. Is the assertion guaranteed? Explain the memory ordering needed for this publication pattern."},{"type":"code","language":"cpp","text":"// Thread A\ndata = 42;\nready.store(true, std::memory_order_release);\n// Thread B\nif (ready.load(std::memory_order_relaxed)) {\n  assert(data == 42);\n}"}]'::jsonb,'candidate','candidate-content-v1');
insert into private.rubrics(question_version_id,version,pass_score,required_claims,reference_answer) values('10000000-0000-4000-8000-000000000002','rubric-v1',3,array['A relaxed load does not synchronize with the release store.','The non-atomic data accesses lack happens-before and can race.','An acquire load reading the release value publishes the prior write.'],'The assertion is not guaranteed. A relaxed load does not establish synchronization, so accessing non-atomic data can race. Use an acquire load that reads the release store''s value. Then the release/acquire synchronizes-with edge orders the preceding data write before the read.');
insert into public.question_versions(id,question_id,version,title,skill,content_blocks,content_review,prompt_version) values('10000000-0000-4000-8000-000000000003','python-async-v1',1,'An async endpoint blocks','Python · Async execution','[{"type":"text","text":"An asyncio-based web endpoint calls time.sleep(2) inside async def. Under load, unrelated requests stall. Explain why async syntax did not prevent the stall and give two suitable remedies."},{"type":"code","language":"python","text":"async def handle():\n    time.sleep(2)\n    return {\"ok\": True}"}]'::jsonb,'candidate','candidate-content-v1');
insert into private.rubrics(question_version_id,version,pass_score,required_claims,reference_answer) values('10000000-0000-4000-8000-000000000003','rubric-v1',3,array['time.sleep blocks the event-loop thread.','Async tasks cooperate at await points; async def alone does not offload work.','Use asyncio.sleep for waiting or offload blocking I/O with asyncio.to_thread.'],'async def does not create a thread. time.sleep blocks the event-loop thread instead of yielding. Use await asyncio.sleep for a timer, or await asyncio.to_thread for unavoidable blocking I/O. CPU-bound work may need a process or separate worker, not unlimited thread offloading.');
insert into public.question_versions(id,question_id,version,title,skill,content_blocks,content_review,prompt_version) values('10000000-0000-4000-8000-000000000004','distributed-idempotency-v1',1,'A payment response is lost','Distributed systems · Idempotency','[{"type":"text","text":"A payment request commits, but the client times out before receiving the response. Design retries that do not charge twice. Include concurrent retries, reusing a key with different input, and the limit of an application database transaction around an external payment API."}]'::jsonb,'candidate','candidate-content-v1');
insert into private.rubrics(question_version_id,version,pass_score,required_claims,reference_answer) values('10000000-0000-4000-8000-000000000004','rubric-v1',3,array['Persist a scoped idempotency key and canonical request fingerprint.','Use a uniqueness constraint and atomic claim/result recording for concurrent retries.','Use the provider''s idempotency support or reconcile uncertain external outcomes; a local transaction cannot roll back an external charge.'],'Scope the key to the user and payment operation. Persist its canonical payload fingerprint and result under a unique constraint. Return the prior result on identical retry and reject a different payload. Serialize concurrent claims. Pass a stable key to the payment provider and reconcile uncertain results. A local database transaction alone cannot undo or atomically encompass an external charge.');
insert into public.question_versions(id,question_id,version,title,skill,content_blocks,content_review,prompt_version) values('10000000-0000-4000-8000-000000000005','architecture-boundaries-v1',1,'Split the service, or keep one deploy?','Architecture · Trade-offs','[{"type":"text","text":"A three-person team maintains one reliable deployment. A new analytics feature has different latency needs but no measured scaling problem. Compare a modular monolith with a new microservice. Give a default, measurable reasons to revisit it, and the operational costs of the split."}]'::jsonb,'candidate','candidate-content-v1');
insert into private.rubrics(question_version_id,version,pass_score,required_claims,reference_answer) values('10000000-0000-4000-8000-000000000005','rubric-v1',3,array['Default to explicit module boundaries without a speculative split.','Name independent scaling/deployment or ownership evidence that could justify a split.','Account for network failure, consistency, observability and deployment costs.'],'Keep one deploy with explicit analytics boundaries until measured isolation, independent scaling or ownership needs justify extraction. Define latency/resource/error-budget signals and revisit when they show contention. A new service adds network failures, data consistency, authentication, telemetry, deployment and on-call overhead. A split can still be justified if the benefits exceed those measured costs.');
